L36_1[2] = L38_1
L37_1 = {}
L38_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_HARMONY_C_TRUMPET"
L39_1 = "ลูน่าเป็นพลตั้งรับทางอากาศที่จะดูดซับเอาดาเมจของฝ่ายเดียวกันไว้และสร้างบาเรียขึ้นมา\nเมื่ออยู่ในเอลีเซียมฟิลฮาร์โมนิก เธอรับหน้าที่เล่นเครื่องดนตรีทองเหลือง ทีแรกเธอก็แค่เป็นสมาชิกชั่วคราว แต่วาทยกรก็เห็นคุณค่าในตัวเธออย่างรวดเร็วด้วยความสามารถในการแสดงที่ผิดคาด\nแม้เธอจะเป็นแชโดว์ที่อ่อนแอกว่าใครเพราะอัตราการตายสูงมาก แต่เธอก็ยังคงเป็นสมาชิกระดับนำด้วยความมุ่งมั่นจะรักษาตำแหน่งในวงไว้\nถ้าเพื่อให้รอดชีวิตแล้วละก็ เธอยินดีจะคุกเข่าให้แม้แต่มนุษย์ ความชอบรับประทานอาหารของเธอก็เป็นข้อบ่งชี้เรื่องที่แชโดว์จะหมกมุ่นกับอะไรบางอย่าง\nและนี่ก็ช่วยอธิบายความลังเลใจบางประการที่จะต้องขุ่นข้องหมองใจในมนุษย์ได้ด้วย"
L37_1[1] = L38_1
L37_1[2] = L39_1
