L10_1[2] = L12_1
L11_1 = {}
L12_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_STREGA_1_INTERLUDE_1"
L13_1 = "ขอต้อนรับสู่คาเฟ่แม่มด สเตรก้า!\nที่นี่จะทำให้คุณได้หลบหนีจากชีวิตประจำวันที่น่าเบื่อ และเพลิดเพลินกับเวทมนตร์เร้นลับและน้ำยาวิเศษแสนหวานของเรา\nเพิ่งเคยมาครั้งแรกใช่ไหม? เชิญอ่านคำแนะนำของคาเฟ่ก่อนเลย"
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
L13_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_STREGA_2_INTERLUDE_3"
L14_1 = "แม่มดไม่เชื่อเรื่องวิทยาศาสตร์ แต่แม่มดเองก็มองข้ามพลังของพันธุกรรมไม่ได้"
L12_1[1] = L13_1
L12_1[2] = L14_1
L13_1 = {}
L14_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_MAID_C_MASK"
L15_1 = "ลิลลี่คือพลซัพพอร์ตที่สามารถตัดกำลังข้อดีของคลาสของเป้าหมาย และทำให้ศัตรูแนวหลังสลบได้\n\nเธอใช้ทุกสิ่งที่ใช้ได้... ไม่ว่าจะเป็นเพลงกล่อม เตียงฟูก หรือแม้แต่ยานอนหลับทันทีและอาวุธปืน... เพื่อที่จะกำจัดศัตรูที่ทำให้นายท่านของเธอฝันร้าย แน่นอนว่าเธออ้างว่าปัจจุบันนี้เธอใช้แต่วิธีกลางๆ เช่น สุคนธบำบัด\nลิลลี่เป็นรุ่นพี่ผู้เข้มงวดของโมเนต์และไลโคริส เธอกำลังเรียนรู้วิธีเข้าสังคมให้เก่งขึ้น ด้วยความช่วยเหลือจากหัวหน้าเมดของเธอ"
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
L15_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_REPLACER_CA_KING"
L16_1 = "รีเพลสเซอร์ คิงเป็นพลตั้งรับที่มีความสามารถในการเรียกทหารหลายนายมา และในบางสถานการณ์ก็สามารถโจมตีเป็นวงกว้างได้อย่างไร้ขีดจำกัด\n\nนอกจากนี้ เขายังเป็นผู้ก่อตั้งรีเพลสเซอร์ซินดิเคต องค์กรที่เหล่าสมาชิกคนสำคัญต่างเป็นผู้สนับสนุนที่ศรัทธาในอุดมการณ์ของเขาอย่างแรงกล้า พวกคนทรยศบอกว่าคนอื่นๆ ในองค์กรเห็นเขาเป็นผู้บุกเบิก \nเขาเก็บตัวตนไว้เป็นความลับได้ไม่ว่าหน่วยข่าวกรองทั้งหลายจะพยายามอย่างขยันขันแข็งเพียงใดก็ตาม บางคนก็สงสัยว่าเขาอาจทำงานให้หรน่วยข่าวกรอง หรือไม่ก็กองทหารนอกกฎหมายที่ทำปฏิบัติการลับ"
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_REPLACER_CA_QUEEN"
L17_1 = "รีเพลสเซอร์ ควีนเป็นพลซุ่มยิงที่ใช้ดีบัฟควบคุมศัตรูและเสริมความแข็งแกร่งให้ตัวเองอย่างต่อเนื่องด้วยการโจมตีเป็นวงกว้าง\n\nปัจจุบันรักษาการแทนคิงและทำหน้าที่คอยนำองค์กร ความอันตรายของเธอนั้นถือว่าอยู่ในระดับเดียวกับวัตถุคอร์รัปต์คลาส 4 และด้วยความที่เธอขมีขมันกับการกำจัดสายลับทั้งหลายในองค์กร เลยทำให้ไม่มีข้อมูลอะไรแพร่งพรายออกมาภายนอกนัก\nแต่จากข้อมูลที่เรามี เธอเป็นผู้สนับสนุนที่ศรัทธาในตัวคิงอย่างแรงกล้า ทว่าไม่ได้สนใจอะไรในอุดมการณ์ของเขานัก"
L15_1[1] = L16_1
L15_1[2] = L17_1
L16_1 = {}
L17_1 = "SI_COLLECTION_UNIT_INTRO_OPR_REPLACER_COMMANDAR"
L18_1 = "เหล่าผู้สนับสนุนอุดมการณ์อันบิดเบี้ยวของรีเพลสเซอร์ซินดิเคตนั้นมีอดีตเจ้าหน้าที่ทางการทหารอยู่ด้วย พวกเขาใช้ความรู้และประสบกาณณ์ที่เคยมีคราวครั้งยังอยู่ใยกองทัพมาฝึกฝนคนอื่นๆ อย่างเป็นระบบและมีกลยุทธ์ คุณูปการข้อนั้นทำให้องค์กรของพวกเขาเติบโตามาเป็นภัยคุกคามของโลกอย่างแท้จริง พวกเขาหลายคนยอมจำนวนไปในการต่อสู้ แต่ส่วนใหญ่แล้วยังคงเชื่อว่าตนเองเป็นผู้ที่ถูกเลือก"
L16_1[1] = L17_1
