L48_1 = "SI_PF_TUTORIAL_TEXUTRE_SYSTEM_COLLETION_2_DESC"
L49_1 = "<COLOR=#FFBC00>สะสมสมาชิกทุกคนในทีมเดียวกัน</COLOR>เพื่อรับรางวัลสร้างทีม\nไปเก็บสมาชิกที่คุณยังไม่มี!"
L47_1[1] = L48_1
L47_1[2] = L49_1
