L8_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_POLICE_LEE_YUMI"
L9_1 = "ลี ยูมี คือพลตั้งรับของ SWAT 4 ที่ต่อสู้ในแนวหน้าด้วยทักษะการหลบหลีกชั้นยอด\n\nแม้ว่าเธอจะเป็นเจ้าหน้าที่ตำรวจ เธอก็เป็นปฏิบัติต่ออาชญากรมากเสียจน เธอมักเลือกที่จะเหวี่ยงดาบแทนที่จะจับพวกเขาใส่กุญแจมือ พฤติกรรมของเธอตกเป็นที่วิพากษ์วิจารณ์ ของสื่ออยู่ตลอด แต่ในฐานะเคาน์เตอร์คนเดียวในกรมตำรวจที่มีสถิติการจับคนร้ายได้มากที่สุด เธอจึงเป็นคนที่ใครก็แตะต้องไม่ได้ แม้แต่ผู้บังคับบัญชา\nคัง โซยอง เพื่อนร่วมงานของเธอรู้ข้อนี้ดีและมักพยายามโอนงานที่ต้องรับผิดชอบไปให้ยูมี ทั้งสองมีปากเสียงกันอยู่เสมอ แต่เมื่อถึงคราวต้องปราบอาชญากรรม พวกเธอจะกลายเป็นคู่หูที่ดีที่สุด การที่ ยูมีมักยุ่งอยู่กับการวิ่งเข้าหาสถานที่เกิดเหตุ เจ้าของร้านขนมปังทั้งหมดในละแวกต่างจำหน้าเธอได้"
L7_1[1] = L8_1
L7_1[2] = L9_1
L8_1 = {}
L9_1 = "SI_SHIP_SKILL_NAME_X_RAZANGRIFF_BIO_HYPER1"
L10_1 = "ไอออนบลาสเตอร์"
