L34_1 = {}
L35_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_ZODIAC_YANG_HANSOL"
L36_1 = "อัศวินแห่งราศีเมษ ยัง ฮันซล เป็นพลจู่โจมที่ทำให้ศัตรูถอยหลังด้วยพลังดาบ\n\nพลังของเขาเพิ่งตื่นขึ้นไม่นานนัก และเขาก็เข้าร่วมกลุ่มอัศวินจักรราศีในฐานะผู้ช่วย ด้วยไม่แน่ใจในความสามารถของตัวเอง จึงทำให้เขาซ้อมฟาดดาบไม้ไผ่วันละหมื่นครั้ง โดยหวังว่าสักวันเขาจะได้กลายเป็นอัศวินจริงๆ ทว่าการทดสอบก็พิสูจน์แล้วว่าศักยภาพของเขาเหนือกว่าเคาน์เตอร์ทั่วๆไปอย่างมาก มีแต่เขาเท่านั้นที่ยังไม่รู้ตัว\nสิ่งที่เขาต้องการ คือเวลา ไม่ใช่การออกกำลังกาย แต่อัศวินคนอื่นๆ ตกลงกันว่าจะเงียบๆไว้ ไม่บอกเขาจนกว่าเขาจะค้นพบสิ่งนี้ด้วยตัวเอง เพราะพวกเขาก็ไม่อยากที่จะขัดขวางความกระตือรือร้นที่จะพัฒนาตัวเขาเองโดยไม่จำเป็น"
L34_1[1] = L35_1
L34_1[2] = L36_1
L35_1 = {}
