L40_1[2] = L42_1
L41_1 = {}
L42_1 = "SI_PF_TUTORIAL_TEXUTRE_BOSS_GUIDE_RAID_DESC_01_03"
L43_1 = "บริตร้าจะ<COLOR=#FFBC00>ได้รับบาเรียและเริ่มรวบรวมพลังเมื่อเหลือเวลาต่อสู้ 1 นาที 20 วินาที</COLOR>\nเมื่อบริตร้า<COLOR=#FFBC00>รวบรวมพลัง ให้ระดมโจมตีบริตร้าเพื่อหยุดยั้งมัน</COLOR>\nหากหยุดยั้งไม่สำเร็จ บริตร้าจะทำดาเมจมหาศาลให้ยานรบและพนักงานของคุณ\nหากหยุดยั้งสำเร็จ บริตร้าจะสตันไปชั่วขณะหนึ่ง และคุณทำดาเมจมหาศาลได้ด้วยการระดมโจมตี\n※ บริตร้าจะทำเช่นนั้นเฉพาะ<COLOR=#FFBC00>เมื่อพลังชีวิตของมันต่ำกว่า 85% ของพลังชีวิตสูงสุด</COLOR>\n※ บริตร้าจะสร้างบาเรียเป็นสัดส่วนกับพลังชีวิตตามเลเวลของมัน"
L41_1[1] = L42_1
L41_1[2] = L43_1
L42_1 = {}
L43_1 = "SI_PF_TUTORIAL_TEXUTRE_BOSS_GUIDE_RAID_DESC_02_01"
L44_1 = "บริตร้าแห่งสายฟ้าฟาด: [ฝันร้าย] จะ<COLOR=#FFBC00>สร้างโซนดีบัฟซึ่งลดการฮีล</COLOR>อย่างต่อเนื่อง\nการโจมตีพื้นฐานของบริตร้าจะทำดาเมจวงกว้าง\nแนะนำให้อัปเกรดยานรบของคุณเพราะบริตร้าจะโจมตีใส่ยานรบโดยตรงด้วย"
L42_1[1] = L43_1
