L1_1[2] = L3_1
L2_1 = {}
L3_1 = "SI_SKIN_DESC_NKM_UNIT_HARMONY_C_VIOLIN_SUMMER"
L4_1 = "รีสอร์ทที่อบอวลด้วยบรรยากาศของฤดูร้อน\nนักร้องพเนจรผู้แจ่มใสปรากฏตัวขึ้นที่นั่น\nความสามารถของเธอนั้นไร้ที่ติ อีกทั้งเพลงที่เลือกก็จับใจผู้คน\nเร่เข้ามา มาดูการแสดงที่ทำให้เหล่าผู้มาพักร้อนได้ยินดี\n\n<color=#ffd34c>นั่นคุณเหรอคะผู้จัดการ? มาเตรียมอุปกรณ์ให้ฉันสิคะ</color>"
L2_1[1] = L3_1
L2_1[2] = L4_1
