L4_1 = "SI_SKIN_TITLE_NKM_UNIT_HARMONY_C_VIOLIN_SUMMER"
L5_1 = "การแสดงขณะพักร้อน"
L3_1[1] = L4_1
L3_1[2] = L5_1
L4_1 = {}
L5_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_SECURITY_C_SERGEANT"
L6_1 = "คริสเป็นพลยิงจู่โจมสายสนับสนุนที่เอาตัวรอดด้วยการรักษาระยะห่างระหว่างเธอกับศัตรู สกิลไม้ตายของเธอทำดาเมจสร้างความผิดปกติแก่ศัตรูในระยะและฟื้นฟูคะแนนวางทัพ\nจ่าคริสตินา เบรชต์ เป็นคนเดียวที่ได้เหรียญเชิดชูเกียรติทั้งที่ยังมีชีวิตอยู่ และได้มาตอนก่อตั้งโกรเนีย แม้จะไม่เคยผ่านการฝึกทหารตามหลักสูตรก่อนถูกส่งไปแนวหน้า แต่เธอก็รอดชีวิตกลับมาจากการต่อสู้ครั้งที่น่ากลัวที่สุดหลายๆ ครั้งได้ด้วยซ้ำ นั่นทำให้ความยอดเยี่ยมของเธอเป็นที่พิศวงงงงวยไปทั่ว ในบรรดาผู้ที่เธอเคยช่วยไว้นั้นบางรายก็เป็นเจ้าหน้าที่ระดับสูง โดยเฉพาะในศึกฤดูใบไม้ผลิที่เป็นดั่งฝันร้ายของกองทัพ\nรัฐบาลพยายามจะเพิ่มขวัญกำลังใจให้ทหารด้วยการทำให้เด็กสาวผู้นี้เป็นประวัติศาสตร์วีรสตรีสงครามที่ยังมีชีวิต และในเมื่อตอนนี้เธอได้รับแต่งตั้งให้ไปอยู่ที่กระทรวงความมั่นคงแห่งชาติเป็นการชั่วคราว นั่นก็มีความหมายเกินกว่าที่จะเป็นเพียงการโฆษณาชวนเชื่ออย่างเปิดเผย"
L4_1[1] = L5_1
L4_1[2] = L6_1
