L34_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_SHARKS_C_KNIFE@AB_UI_UNIT_VOICE_NKM_UNIT_SHARKS_C_KNIFE_LOBBY_TOUCH_NORMAL_2"
L35_1 = "ประโยชน์ของการเป็นเคาน์เตอร์  ทำอาหารเป็นอะไรบ้าง? ไม่มีอะไรพิเศษ... แต่ถ้าฉันต้องเลือกสักอย่าง ฉันรู้วิธีแล่เนื้อปลากลางอากาศนะ"
L33_1[1] = L34_1
L33_1[2] = L35_1
L34_1 = {}
L35_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_SHARKS_C_KNIFE@AB_UI_UNIT_VOICE_NKM_UNIT_SHARKS_C_KNIFE_LOBBY_TOUCH_NORMAL_3"
L36_1 = "เป็นตำราที่คุณเลือกคู่ต่อสู้ที่ดูอ่อนแอที่สุดเมื่อต่อสู้ แต่ฉันไม่แนะนำให้เลือกเพียงรูปลักษณ์ภายนอกเท่านั้น มีคนโง่ที่กลัวรอยแผลเป็นของฉัน ดังนั้นพวกเขาจึงติดตามกัปตันดราเคเชียแทน... เอาล่ะ ฉันไม่จำเป็นต้องบอกคุณว่ามันจบลงอย่างไร"
L34_1[1] = L35_1
L34_1[2] = L36_1
