L36_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_SHARKS_C_KNIFE@AB_UI_UNIT_VOICE_NKM_UNIT_SHARKS_C_KNIFE_LOBBY_TOUCH_NORMAL_4"
L37_1 = "ขณะอ่านหนังสือ ฉันได้รู้ว่าปลาเกือบจะสูญพันธุ์เนื่องจากมีเรือประมงมากมายมาจับปลา แต่ตอนนี้ฉันไม่ต้องกังวลเกี่ยวกับเรื่องนั้นอีกแล้ว แม้ว่าท้องทะเลจะเต็มไปด้วยวัตถุคอร์รัปต์ก็ตาม"
L35_1[1] = L36_1
L35_1[2] = L37_1
